# Flat mapping: business name -> category
BIZ_TYPES = {}
for cat, names in BIZ_CATEGORIES.items():
    for n in names:
        BIZ_TYPES[n] = cat

def get_schema_for_business(biz_name):
    """Return (category, title) for a business name."""
    cat = BIZ_TYPES.get(biz_name)
    if not cat:
        return None, None
    title = biz_name.replace(" & ", "_").replace(" ", "_") + "_Database"
    return cat, title

def list_businesses():
    total = len(BIZ_TYPES)
    print(f"Available businesses ({total}):")
    for cat, names in BIZ_CATEGORIES.items():
        print(f"\n  [{cat}]")
        for j, n in enumerate(names, 1):
            print(f"    {j:3d}. {n}")

